inline bool TableWriteTestData( TableWriter & w, const TestData & value )
{
    if ( value.a != 0 )
    {
        w.put16( 0xcd20 ); w.put8( 4 ); // a
        w.put32( uint32_t( value.a ) );
    }
    if ( value.b != 0 )
    {
        w.put16( 0xcae9 ); w.put8( 4 ); // b
        w.put32( uint32_t( value.b ) );
    }
    if ( value.c != 0 )
    {
        w.put16( 0xca5e ); w.put8( 4 ); // c
        w.put32( uint32_t( value.c ) );
    }
    if ( value.d != 0 )
    {
        w.put16( 0xc57f ); w.put8( 6 ); // d
        w.put8( uint8_t( value.d ) );
    }
    if ( value.e != 0 )
    {
        w.put16( 0xc2ec ); w.put8( 6 ); // e
        w.put8( uint8_t( value.e ) );
    }
    if ( value.f != 0 )
    {
        w.put16( 0xc495 ); w.put8( 6 ); // f
        w.put8( uint8_t( value.f ) );
    }
    if ( value.g != false )
    {
        w.put16( 0xc40a ); w.put8( 1 ); // g
        w.put8( value.g ? 1 : 0 );
    }
    if ( value.items_count > 0 )
    {
        w.put16( 0x09f6 ); w.put8( 14 ); // items
        int64_t len_at_items = w.offset; w.put32( 0 );
        w.put8( 4 ); w.put16( uint16_t( value.items_count ) );
        for ( int32_t i = 0; i < value.items_count; i++ )
        {
            w.put32( uint32_t( value.items[i] ) );
        }
        w.patch32( len_at_items, uint32_t( w.offset - len_at_items - 4 ) );
    }
    if ( value.float_value != 0.0f )
    {
        w.put16( 0xbbaf ); w.put8( 10 ); // float_value
        w.put32( table_float_to_bits( value.float_value ) );
    }
    if ( value.compressed_float_value != 0.0f )
    {
        w.put16( 0x8aa5 ); w.put8( 10 ); // compressed_float_value
        w.put32( table_float_to_bits( value.compressed_float_value ) );
    }
    if ( value.double_value != 0.0 )
    {
        w.put16( 0x6a50 ); w.put8( 11 ); // double_value
        w.put64( table_double_to_bits( value.double_value ) );
    }
    if ( value.int8_value != 0 )
    {
        w.put16( 0x6592 ); w.put8( 2 ); // int8_value
        w.put8( uint8_t( value.int8_value ) );
    }
    if ( value.int16_value != 0 )
    {
        w.put16( 0x68f3 ); w.put8( 3 ); // int16_value
        w.put16( uint16_t( value.int16_value ) );
    }
    if ( value.uint8_value != 0 )
    {
        w.put16( 0x5645 ); w.put8( 6 ); // uint8_value
        w.put8( uint8_t( value.uint8_value ) );
    }
    if ( value.uint16_value != 0 )
    {
        w.put16( 0xd185 ); w.put8( 7 ); // uint16_value
        w.put16( uint16_t( value.uint16_value ) );
    }
    if ( value.uint32_value != 0 )
    {
        w.put16( 0x3ba7 ); w.put8( 8 ); // uint32_value
        w.put32( uint32_t( value.uint32_value ) );
    }
    if ( value.uint64_value != 0 )
    {
        w.put16( 0xc4d6 ); w.put8( 9 ); // uint64_value
        w.put64( uint64_t( value.uint64_value ) );
    }
    if ( value.int64_full != 0 )
    {
        w.put16( 0xc2b7 ); w.put8( 5 ); // int64_full
        w.put64( uint64_t( value.int64_full ) );
    }
    if ( value.int64_range != 0 )
    {
        w.put16( 0xab05 ); w.put8( 5 ); // int64_range
        w.put64( uint64_t( value.int64_range ) );
    }
    {
        w.put16( 0x14fc ); w.put8( 14 ); // fixed_bytes (fixed [17])
        int64_t len_at_fixed_bytes = w.offset; w.put32( 0 );
        w.put8( 6 ); w.put16( 17 );
        for ( int32_t i = 0; i < 17; i++ )
        {
            w.put8( uint8_t( value.fixed_bytes[i] ) );
        }
        w.patch32( len_at_fixed_bytes, uint32_t( w.offset - len_at_fixed_bytes - 4 ) );
    }
    if ( value.text_length > 0 )
    {
        w.put16( 0xf3d8 ); w.put8( 12 ); // text
        w.put16( uint16_t( value.text_length ) );
        w.raw( value.text, value.text_length );
    }
    w.put16( 0 ); // terminator
    return !w.overflow;
}

